import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-07-20/nav2_theta_star_cover.png",n="/Nav2ArticlesSite/article-assets/2026-07-20/nav2_theta_star_01_architecture.png",c="/Nav2ArticlesSite/article-assets/2026-07-20/nav2_theta_star_02_lifecycle.png",i="/Nav2ArticlesSite/article-assets/2026-07-20/nav2_theta_star_03_interfaces.png",d="/Nav2ArticlesSite/article-assets/2026-07-20/nav2_theta_star_04_cost_model.png",h="/Nav2ArticlesSite/article-assets/2026-07-20/nav2_theta_star_05_lazy_search.png",s="/Nav2ArticlesSite/article-assets/2026-07-20/nav2_theta_star_06_output_outcomes.png",f=JSON.parse('{"title":"栅格只能横平竖直？拆解 Theta* 如何用视线检查走出任意角全局路径","description":"nav2thetastarplanner 不启动独立 ROS 2 节点，也不自己订阅地图、目标点或 TF。它被编译成共享库，并以 nav2core::GlobalPlanner 插件的身份装入 plannerserver。","frontmatter":{"title":"栅格只能横平竖直？拆解 Theta* 如何用视线检查走出任意角全局路径","description":"nav2thetastarplanner 不启动独立 ROS 2 节点，也不自己订阅地图、目标点或 TF。它被编译成共享库，并以 nav2core::GlobalPlanner 插件的身份装入 plannerserver。","date":"2026-07-20","section":"二 · 全局规划与路径搜索","readingTime":9,"source":"2026-07-20/nav2_theta_star_planner_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-20/nav2_theta_star_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-theta-star-planner-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"栅格只能横平竖直？拆解 Theta* 如何用视线检查走出任意角全局路径"}],["meta",{"property":"og:description","content":"nav2thetastarplanner 不启动独立 ROS 2 节点，也不自己订阅地图、目标点或 TF。它被编译成共享库，并以 nav2core::GlobalPlanner 插件的身份装入 plannerserver。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-theta-star-planner-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-20/nav2_theta_star_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-20"}],["meta",{"name":"twitter:title","content":"栅格只能横平竖直？拆解 Theta* 如何用视线检查走出任意角全局路径"}],["meta",{"name":"twitter:description","content":"nav2thetastarplanner 不启动独立 ROS 2 节点，也不自己订阅地图、目标点或 TF。它被编译成共享库，并以 nav2core::GlobalPlanner 插件的身份装入 plannerserver。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-20/nav2_theta_star_cover.png"}]],"prev":{"text":"同样是 A*，Nav2 为什么给了两套答案？NavFn 与 Smac2D 全数据流拆解","link":"/nav2/nav2-gridbasedastar-vs-smac2d-full-dataflow"},"next":{"text":"局部路径为什么会“变形”？拆解 TEB 如何把空间、时间和避障压进一张优化图","link":"/nav2/teb-local-planner-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-theta-star-planner-full-dataflow.md","filePath":"nav2/nav2-theta-star-planner-full-dataflow.md","lastUpdated":null}'),p={name:"nav2/nav2-theta-star-planner-full-dataflow.md"};function _(u,a,m,b,q,v){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="栅格只能横平竖直-拆解-theta-如何用视线检查走出任意角全局路径" tabindex="-1">栅格只能横平竖直？拆解 Theta* 如何用视线检查走出任意角全局路径 <a class="header-anchor" href="#栅格只能横平竖直-拆解-theta-如何用视线检查走出任意角全局路径" aria-label="Permalink to &quot;栅格只能横平竖直？拆解 Theta* 如何用视线检查走出任意角全局路径&quot;">​</a></h1><blockquote><p>本文基于当前项目中的 <code>nav2_theta_star_planner</code> 源码，逐层拆解它在 Nav2 中的真实调用位置、生命周期状态、输入输出和 Lazy Theta* 搜索数据流。文中同时区分算法设计与当前仓库实现边界。</p></blockquote><p><img src="'+l+'" alt="封面：Theta* 任意角全局规划"></p><h2 id="一、先给结论-它不是节点-而是一段被调用的规划能力" tabindex="-1">一、先给结论：它不是节点，而是一段被调用的规划能力 <a class="header-anchor" href="#一、先给结论-它不是节点-而是一段被调用的规划能力" aria-label="Permalink to &quot;一、先给结论：它不是节点，而是一段被调用的规划能力&quot;">​</a></h2><p><code>nav2_theta_star_planner</code> 不启动独立 ROS 2 节点，也不自己订阅地图、目标点或 TF。它被编译成共享库，并以 <code>nav2_core::GlobalPlanner</code> 插件的身份装入 <code>planner_server</code>。</p><p>对外只有六个关键入口：</p><ul><li><code>configure()</code>：接收父节点、插件名、TF Buffer 和全局 Costmap。</li><li><code>activate()</code>：注册动态参数回调。</li><li><code>deactivate()</code>：进入非活动状态。</li><li><code>cleanup()</code>：释放搜索器。</li><li><code>createPlan()</code>：接收已变换到全局地图坐标系的起点和终点，返回 <code>nav_msgs::msg::Path</code>。</li><li>动态参数回调：更新搜索方向数、未知区域策略和代价权重。</li></ul><p>所以，用户在导航时看到的规划 Action、服务端状态和路径话题，属于 <code>nav2_planner</code>；Theta* 只负责其中“根据一张代价地图算出一条路”的核心步骤。</p><p><img src="'+n+'" alt="图 1：Theta* 在 Nav2 中的位置"></p><h2 id="二、插件是怎样被调用的" tabindex="-1">二、插件是怎样被调用的 <a class="header-anchor" href="#二、插件是怎样被调用的" aria-label="Permalink to &quot;二、插件是怎样被调用的&quot;">​</a></h2><p>插件 XML 将 <code>nav2_theta_star_planner/ThetaStarPlanner</code> 映射到 C++ 类型 <code>nav2_theta_star_planner::ThetaStarPlanner</code>。<code>PlannerServer</code> 根据参数中的插件 ID 创建实例，随后由生命周期管理器推动配置、激活、停用和清理。</p><p>一次典型调用沿着下面的链路发生。</p><h3 id="_2-1-上层导航器发送目标" tabindex="-1">2.1 上层导航器发送目标 <a class="header-anchor" href="#_2-1-上层导航器发送目标" aria-label="Permalink to &quot;2.1 上层导航器发送目标&quot;">​</a></h3><p>上层导航器向 <code>ComputePathToPose</code> 或 <code>ComputePathThroughPoses</code> Action 发送目标。</p><h3 id="_2-2-plannerserver-获取并变换位姿" tabindex="-1">2.2 PlannerServer 获取并变换位姿 <a class="header-anchor" href="#_2-2-plannerserver-获取并变换位姿" aria-label="Permalink to &quot;2.2 PlannerServer 获取并变换位姿&quot;">​</a></h3><p><code>PlannerServer</code> 获得机器人当前位姿，并把起点、终点变换到全局 Costmap 的坐标系。</p><h3 id="_2-3-plannerserver-选择插件" tabindex="-1">2.3 PlannerServer 选择插件 <a class="header-anchor" href="#_2-3-plannerserver-选择插件" aria-label="Permalink to &quot;2.3 PlannerServer 选择插件&quot;">​</a></h3><p><code>PlannerServer</code> 根据 planner ID 选择 Theta* 插件。</p><h3 id="_2-4-进程内调用规划器" tabindex="-1">2.4 进程内调用规划器 <a class="header-anchor" href="#_2-4-进程内调用规划器" aria-label="Permalink to &quot;2.4 进程内调用规划器&quot;">​</a></h3><p>PlannerServer 在进程内直接调用 <code>createPlan(start, goal)</code>，不是通过 ROS 话题或服务调用。</p><h3 id="_2-5-theta-执行搜索" tabindex="-1">2.5 Theta* 执行搜索 <a class="header-anchor" href="#_2-5-theta-执行搜索" aria-label="Permalink to &quot;2.5 Theta* 执行搜索&quot;">​</a></h3><p>Theta* 锁住 Costmap，完成坐标转换、搜索、回溯和插值。</p><h3 id="_2-6-返回路径" tabindex="-1">2.6 返回路径 <a class="header-anchor" href="#_2-6-返回路径" aria-label="Permalink to &quot;2.6 返回路径&quot;">​</a></h3><p>返回的 <code>Path</code> 再由 <code>PlannerServer</code> 交给上层导航流程和控制器。</p><p>当前 <code>nav2_regulated_modules</code> 参数确实加载了名为 <code>ThetaStar</code> 的插件，但 <code>selected_planner</code> 仍是 <code>GridBasedAstar</code>。这意味着 Theta* 已可被显式选择，却不是该配置下的默认规划器。</p><h2 id="三、生命周期-资源在什么时候出现" tabindex="-1">三、生命周期：资源在什么时候出现 <a class="header-anchor" href="#三、生命周期-资源在什么时候出现" aria-label="Permalink to &quot;三、生命周期：资源在什么时候出现&quot;">​</a></h2><p><code>configure()</code> 创建内部 <code>ThetaStar</code> 搜索对象，保存 Costmap 指针与全局坐标系，并读取六类规划参数。<code>activate()</code> 才添加动态参数回调；<code>cleanup()</code> 将搜索对象置空。</p><p>从状态角度看，它依附于 <code>planner_server</code>。</p><h3 id="_3-1-未配置" tabindex="-1">3.1 未配置 <a class="header-anchor" href="#_3-1-未配置" aria-label="Permalink to &quot;3.1 未配置&quot;">​</a></h3><p>只有插件对象，没有可用搜索器。</p><h3 id="_3-2-非活动" tabindex="-1">3.2 非活动 <a class="header-anchor" href="#_3-2-非活动" aria-label="Permalink to &quot;3.2 非活动&quot;">​</a></h3><p>搜索器已创建，但服务端不对外执行规划任务。</p><h3 id="_3-3-活动" tabindex="-1">3.3 活动 <a class="header-anchor" href="#_3-3-活动" aria-label="Permalink to &quot;3.3 活动&quot;">​</a></h3><p>允许 <code>createPlan()</code>，动态参数也可以生效。</p><h3 id="_3-4-已清理" tabindex="-1">3.4 已清理 <a class="header-anchor" href="#_3-4-已清理" aria-label="Permalink to &quot;3.4 已清理&quot;">​</a></h3><p>搜索器被释放，等待下一次配置。</p><p><img src="'+c+'" alt="图 2：生命周期与资源状态"></p><p>当前实现有一个生命周期边界：<code>deactivate()</code> 没有注销动态参数回调，<code>cleanup()</code> 也只释放搜索器。如果清理后仍触发参数更新，回调可能访问已经为空的搜索器。工程上更稳妥的做法，是在停用或清理阶段显式重置回调句柄。</p><h2 id="四、输入输出接口-ros-外壳与算法内核要分开看" tabindex="-1">四、输入输出接口：ROS 外壳与算法内核要分开看 <a class="header-anchor" href="#四、输入输出接口-ros-外壳与算法内核要分开看" aria-label="Permalink to &quot;四、输入输出接口：ROS 外壳与算法内核要分开看&quot;">​</a></h2><p>Theta* 的直接输入不是 ROS 话题，而是四组进程内数据：</p><ul><li>起点 <code>geometry_msgs::msg::PoseStamped</code>。</li><li>终点 <code>geometry_msgs::msg::PoseStamped</code>。</li><li><code>Costmap2D</code> 指针，提供分辨率、原点、栅格代价和坐标转换。</li><li>参数快照，控制邻接方向、未知区域和代价模型。</li></ul><p>直接输出只有 <code>nav_msgs::msg::Path</code>。失败不是单独的错误码，而通常表现为空路径，之后由 <code>PlannerServer</code> 转成规划 Action 的失败结果。</p><p>它保存了 TF Buffer，但当前 <code>createPlan()</code> 不调用 TF。也就是说，坐标系一致性由 <code>PlannerServer</code> 在进入插件前保证。</p><p>它没有自己的订阅者、发布者、Service 或 Action；地图更新也不是消息回调进入插件，而是通过共享的 Costmap 对象被读取。</p><p><img src="'+i+'" alt="图 3：完整输入输出边界"></p><h2 id="五、createplan-一条路径从哪里开始长出来" tabindex="-1">五、<code>createPlan()</code>：一条路径从哪里开始长出来 <a class="header-anchor" href="#五、createplan-一条路径从哪里开始长出来" aria-label="Permalink to &quot;五、`createPlan()`：一条路径从哪里开始长出来&quot;">​</a></h2><p><code>createPlan()</code> 先锁住 Costmap 的互斥量，这把锁覆盖整个搜索和路径生成过程。随后依次执行以下步骤。</p><h3 id="_5-1-转换栅格坐标" tabindex="-1">5.1 转换栅格坐标 <a class="header-anchor" href="#_5-1-转换栅格坐标" aria-label="Permalink to &quot;5.1 转换栅格坐标&quot;">​</a></h3><p>将世界坐标的起点、终点转换成地图栅格坐标。</p><h3 id="_5-2-检查地图边界" tabindex="-1">5.2 检查地图边界 <a class="header-anchor" href="#_5-2-检查地图边界" aria-label="Permalink to &quot;5.2 检查地图边界&quot;">​</a></h3><p>如果任一点超出地图边界，立即返回空路径。</p><h3 id="_5-3-处理起终点同栅格" tabindex="-1">5.3 处理起终点同栅格 <a class="header-anchor" href="#_5-3-处理起终点同栅格" aria-label="Permalink to &quot;5.3 处理起终点同栅格&quot;">​</a></h3><p>如果起终点落在同一栅格，检查该栅格是否可通行；可通行时只返回一个点。</p><h3 id="_5-4-执行端点检查与搜索" tabindex="-1">5.4 执行端点检查与搜索 <a class="header-anchor" href="#_5-4-执行端点检查与搜索" aria-label="Permalink to &quot;5.4 执行端点检查与搜索&quot;">​</a></h3><p>普通情况先检查起点和终点安全性，再运行 Theta* 搜索。</p><h3 id="_5-5-回溯路径" tabindex="-1">5.5 回溯路径 <a class="header-anchor" href="#_5-5-回溯路径" aria-label="Permalink to &quot;5.5 回溯路径&quot;">​</a></h3><p>从终点沿父指针回溯到起点，转换成世界坐标。</p><h3 id="_5-6-插值路径" tabindex="-1">5.6 插值路径 <a class="header-anchor" href="#_5-6-插值路径" aria-label="Permalink to &quot;5.6 插值路径&quot;">​</a></h3><p>按 Costmap 分辨率做线性插值，形成输出路径。</p><h3 id="_5-7-设置末端方向" tabindex="-1">5.7 设置末端方向 <a class="header-anchor" href="#_5-7-设置末端方向" aria-label="Permalink to &quot;5.7 设置末端方向&quot;">​</a></h3><p>根据参数决定末端方向使用目标姿态，还是使用最后一段路径的切线方向。</p><p>这里没有“目标容差”逻辑。目标栅格不可通行或完全不可达时，插件直接返回空路径。</p><h2 id="六、代价函数-短、远离障碍、靠近目标之间怎样权衡" tabindex="-1">六、代价函数：短、远离障碍、靠近目标之间怎样权衡 <a class="header-anchor" href="#六、代价函数-短、远离障碍、靠近目标之间怎样权衡" aria-label="Permalink to &quot;六、代价函数：短、远离障碍、靠近目标之间怎样权衡&quot;">​</a></h2><p>当前实现把搜索代价拆为三部分：</p><ul><li>欧氏距离代价：鼓励路径更短。</li><li>穿越代价：由 Costmap 栅格代价转换，并以平方项放大靠近障碍的代价。</li><li>启发代价：用当前位置到目标的欧氏距离引导搜索。</li></ul><p>可以概括为：</p><p><code>f(n) = g(n) + w_heuristic × h(n)</code></p><p>其中 <code>g(n)</code> 累积路径长度与穿越代价；<code>h(n)</code> 是到目标的直线距离。源码还给栅格代价加上固定偏置，使自由空间也有稳定的穿越成本。</p><p>关键参数包括：</p><ul><li><code>how_many_corners</code>：配置阶段只接受 <code>4</code> 或 <code>8</code>，决定四邻域或八邻域扩展。</li><li><code>allow_unknown</code>：是否允许进入 <code>NO_INFORMATION</code> 栅格。</li><li><code>w_euc_cost</code>：欧氏距离项权重。</li><li><code>w_traversal_cost</code>：Costmap 穿越代价权重。</li><li><code>w_heuristic_cost</code>：内部取 <code>min(w_euc_cost, 1.0)</code>。</li><li><code>use_final_approach_orientation</code>：末点方向是否沿用最终接近方向。</li></ul><p><img src="'+d+'" alt="图 4：代价模型与参数作用"></p><p>动态更新还有两个当前实现边界。</p><h3 id="_6-1-how-many-corners-动态更新边界" tabindex="-1">6.1 <code>how_many_corners</code> 动态更新边界 <a class="header-anchor" href="#_6-1-how-many-corners-动态更新边界" aria-label="Permalink to &quot;6.1 `how_many_corners` 动态更新边界&quot;">​</a></h3><p>运行期修改 <code>how_many_corners</code> 时没有再次限制为 <code>4</code> 或 <code>8</code>，大于 <code>8</code> 可能越过固定邻接数组。</p><h3 id="_6-2-w-euc-cost-动态更新边界" tabindex="-1">6.2 <code>w_euc_cost</code> 动态更新边界 <a class="header-anchor" href="#_6-2-w-euc-cost-动态更新边界" aria-label="Permalink to &quot;6.2 `w_euc_cost` 动态更新边界&quot;">​</a></h3><p>运行期修改 <code>w_euc_cost</code> 不会重新计算启发权重，因此搜索启发项仍保持配置阶段的值。</p><h2 id="七、lazy-theta-的核心-能看见祖父节点-就把弯拐直" tabindex="-1">七、Lazy Theta* 的核心：能看见祖父节点，就把弯拐直 <a class="header-anchor" href="#七、lazy-theta-的核心-能看见祖父节点-就把弯拐直" aria-label="Permalink to &quot;七、Lazy Theta* 的核心：能看见祖父节点，就把弯拐直&quot;">​</a></h2><p>普通 A* 的父节点只能来自直接相邻栅格，所以路径天然带有栅格折线。Theta* 的关键是“视线检查”：当前节点准备扩展邻居时，会尝试让邻居绕过当前节点，直接连接当前节点的父节点。</p><p>当前源码采用 Lazy Theta* 风格。</p><h3 id="_7-1-取出最小代价节点" tabindex="-1">7.1 取出最小代价节点 <a class="header-anchor" href="#_7-1-取出最小代价节点" aria-label="Permalink to &quot;7.1 取出最小代价节点&quot;">​</a></h3><p>从优先队列取出总代价最小的节点。</p><h3 id="_7-2-执行视线检查" tabindex="-1">7.2 执行视线检查 <a class="header-anchor" href="#_7-2-执行视线检查" aria-label="Permalink to &quot;7.2 执行视线检查&quot;">​</a></h3><p>在正式扩展前，用改造过的 Bresenham 算法检查它与祖父节点之间是否无遮挡。</p><h3 id="_7-3-重连父节点" tabindex="-1">7.3 重连父节点 <a class="header-anchor" href="#_7-3-重连父节点" aria-label="Permalink to &quot;7.3 重连父节点&quot;">​</a></h3><p>若直连安全且累计代价更低，就把父指针改到祖父节点。</p><h3 id="_7-4-扩展邻域节点" tabindex="-1">7.4 扩展邻域节点 <a class="header-anchor" href="#_7-4-扩展邻域节点" aria-label="Permalink to &quot;7.4 扩展邻域节点&quot;">​</a></h3><p>再扩展四邻域或八邻域节点，更新它们的 <code>g</code>、<code>h</code>、<code>f</code> 与父指针。</p><h3 id="_7-5-判断搜索结束" tabindex="-1">7.5 判断搜索结束 <a class="header-anchor" href="#_7-5-判断搜索结束" aria-label="Permalink to &quot;7.5 判断搜索结束&quot;">​</a></h3><p>直到目标被取出，或开放队列耗尽。</p><p>视线检查不仅判断致命障碍，还会累积沿线的穿越代价，并阻止从障碍角点间斜穿。未知栅格在允许未知区域时可以通过，但会按高代价参与计算。</p><p><img src="'+h+'" alt="图 5：视线检查与父节点重连"></p><h2 id="八、路径回溯、插值和朝向" tabindex="-1">八、路径回溯、插值和朝向 <a class="header-anchor" href="#八、路径回溯、插值和朝向" aria-label="Permalink to &quot;八、路径回溯、插值和朝向&quot;">​</a></h2><p>搜索成功后，父指针形成一棵从目标通向起点的树。<code>backtrace()</code> 先逆序收集节点，再反转成起点到终点的原始路径。随后 <code>linearInterpolation()</code> 按地图分辨率在每段之间插点，让控制器收到更密集的轨迹。</p><p>当前插值实现有三个值得注意的事实：</p><ul><li>每段会插入段首和若干中间点，但没有显式追加原始路径最后一个点，所以输出末点可能停在目标前一个分辨率以内。</li><li><code>Path.header</code> 会写入全局坐标系和时间戳，但每个插值 <code>PoseStamped</code> 的 header 没有同步填充。</li><li>中间点方向保持默认值，只有最后一个输出点会设置目标方向或最终接近方向。</li></ul><p>因此，下游真正应该依赖的是 <code>Path.header.frame_id</code> 和路径几何；若控制器需要每个点都有合法四元数与独立 header，应先修正这里的输出封装。</p><p><img src="'+s+'" alt="图 6：成功路径、失败出口与输出边界"></p><h2 id="九、状态与失败结果全景" tabindex="-1">九、状态与失败结果全景 <a class="header-anchor" href="#九、状态与失败结果全景" aria-label="Permalink to &quot;九、状态与失败结果全景&quot;">​</a></h2><p>一次规划请求内部会经历以下运行状态。</p><h3 id="_9-1-接收请求" tabindex="-1">9.1 接收请求 <a class="header-anchor" href="#_9-1-接收请求" aria-label="Permalink to &quot;9.1 接收请求&quot;">​</a></h3><p>保存起点、终点并锁定 Costmap。</p><h3 id="_9-2-坐标校验" tabindex="-1">9.2 坐标校验 <a class="header-anchor" href="#_9-2-坐标校验" aria-label="Permalink to &quot;9.2 坐标校验&quot;">​</a></h3><p>将世界坐标转换为地图索引。</p><h3 id="_9-3-端点校验" tabindex="-1">9.3 端点校验 <a class="header-anchor" href="#_9-3-端点校验" aria-label="Permalink to &quot;9.3 端点校验&quot;">​</a></h3><p>确认起终点可进入。</p><h3 id="_9-4-搜索中" tabindex="-1">9.4 搜索中 <a class="header-anchor" href="#_9-4-搜索中" aria-label="Permalink to &quot;9.4 搜索中&quot;">​</a></h3><p>开放队列驱动节点扩展和视线重连。</p><h3 id="_9-5-回溯中" tabindex="-1">9.5 回溯中 <a class="header-anchor" href="#_9-5-回溯中" aria-label="Permalink to &quot;9.5 回溯中&quot;">​</a></h3><p>父指针转换为世界坐标折线。</p><h3 id="_9-6-插值中" tabindex="-1">9.6 插值中 <a class="header-anchor" href="#_9-6-插值中" aria-label="Permalink to &quot;9.6 插值中&quot;">​</a></h3><p>按分辨率加密路径并设置末端方向。</p><h3 id="_9-7-成功" tabindex="-1">9.7 成功 <a class="header-anchor" href="#_9-7-成功" aria-label="Permalink to &quot;9.7 成功&quot;">​</a></h3><p>返回非空 <code>Path</code>。</p><h3 id="_9-8-失败" tabindex="-1">9.8 失败 <a class="header-anchor" href="#_9-8-失败" aria-label="Permalink to &quot;9.8 失败&quot;">​</a></h3><p>越界、端点不安全或开放队列耗尽，返回空 <code>Path</code>。</p><p>此外，当前搜索循环先扩展源点再进入弹出循环，源点可能被重复展开；循环退出条件又与“目标是否最后一个出队”耦合。这类边界应通过最小地图回归测试确认，不能只靠正常场景判断算法正确。</p><h2 id="十、落地时最容易踩的坑" tabindex="-1">十、落地时最容易踩的坑 <a class="header-anchor" href="#十、落地时最容易踩的坑" aria-label="Permalink to &quot;十、落地时最容易踩的坑&quot;">​</a></h2><h3 id="_10-1-插件名有两层" tabindex="-1">10.1 插件名有两层 <a class="header-anchor" href="#_10-1-插件名有两层" aria-label="Permalink to &quot;10.1 插件名有两层&quot;">​</a></h3><p>参数中的 ID 可以叫 <code>ThetaStar</code>，但 <code>plugin</code> 字段必须匹配 XML 导出的类型名。</p><h3 id="_10-2-allow-unknown-true-不代表未知区没有代价" tabindex="-1">10.2 <code>allow_unknown=true</code> 不代表未知区没有代价 <a class="header-anchor" href="#_10-2-allow-unknown-true-不代表未知区没有代价" aria-label="Permalink to &quot;10.2 `allow_unknown=true` 不代表未知区没有代价&quot;">​</a></h3><p>它只是允许搜索进入，未知栅格仍会形成很高的穿越成本。</p><h3 id="_10-3-权重不是越大越好" tabindex="-1">10.3 权重不是越大越好 <a class="header-anchor" href="#_10-3-权重不是越大越好" aria-label="Permalink to &quot;10.3 权重不是越大越好&quot;">​</a></h3><p><code>w_traversal_cost</code> 太大会让路径过度远离障碍，<code>w_euc_cost</code> 太大会缩短路径但可能贴近障碍；调整时应同时观察路径长度、最小障碍距离和搜索耗时。</p><h3 id="_10-4-规划期间-costmap-被长时间加锁" tabindex="-1">10.4 规划期间 Costmap 被长时间加锁 <a class="header-anchor" href="#_10-4-规划期间-costmap-被长时间加锁" aria-label="Permalink to &quot;10.4 规划期间 Costmap 被长时间加锁&quot;">​</a></h3><p>大地图、复杂障碍或弱算力平台上，搜索耗时也会变成地图更新阻塞时间。</p><h3 id="_10-5-动态参数并非全部安全" tabindex="-1">10.5 动态参数并非全部安全 <a class="header-anchor" href="#_10-5-动态参数并非全部安全" aria-label="Permalink to &quot;10.5 动态参数并非全部安全&quot;">​</a></h3><p>当前实现缺少部分范围校验、并发保护与派生参数重算，实车更适合在非活动状态修改关键搜索参数。</p><h2 id="十一、结语" tabindex="-1">十一、结语 <a class="header-anchor" href="#十一、结语" aria-label="Permalink to &quot;十一、结语&quot;">​</a></h2><p>Theta* 真正解决的不是“能不能找到路”，而是“如何在栅格地图上少受栅格方向限制”。它通过视线检查重连父节点，让路径更接近连续空间中的直线，同时继续复用 Nav2 的 Costmap、插件体系和 PlannerServer 调度。</p><p>读懂这条数据流后，调参就不再是盲目修改几个权重：先确认调用方和坐标系，再检查端点安全与未知区策略，最后才是欧氏距离、穿越代价和启发权重之间的取舍。</p>',130)])])}const k=e(p,[["render",_]]);export{f as __pageData,k as default};
